DECLARE @empresa NVARCHAR(10) = '{{ $('When Called by Agent').first().json.empresa }}';
DECLARE @tienda  NVARCHAR(10) = '{{ $('When Called by Agent').first().json.tienda }}';
DECLARE @sku     NVARCHAR(50) = '{{ $('When Called by Agent').first().json.sku }}';

-- Stock disponible: misma definicion que ISA Tool - Buscar Productos
-- (SUM(EXISTENCIA) por empresa+tienda+sku). No se resta RESERVA para ser
-- consistente con el stock que muestra el catalogo.
SELECT ISNULL(SUM(EXISTENCIA), 0) AS disponible
FROM dbo.INVENTARIO
WHERE EMPRESA = @empresa AND TIENDA = @tienda AND SKU = @sku;

parameters.jsCode:
const trig = $('When Called by Agent').first().json;
const cart = $('Obtener Carrito').first().json;
const prev = $('Resumen Previo').first().json;
const stockRow = $('Consultar Stock').first().json;

const sku = String(trig.sku);
const qty = Number(trig.qty) || 0;
const disponible = Number(stockRow && stockRow.disponible != null ? stockRow.disponible : 0);

// Cantidad de ESTE sku que ya esta en el carrito (para que sumar no exceda el stock).
const items = (prev && prev.data && Array.isArray(prev.data.items)) ? prev.data.items : [];
const en_carrito = items
  .filter(i => String(i.productCode) === sku)
  .reduce((a, i) => a + (Number(i.quantity) || 0), 0);

const requerido = en_carrito + qty;
const suficiente = requerido <= disponible;

return [{ json: {
  suficiente,
  disponible,
  en_carrito,
  solicitado: qty,
  requerido,
  sku,
  cart_id: (cart && cart.data) ? cart.data.cart_id : null
} }];

